function handleThriveLevelChange() {
    const thriveLevel = document.getElementById('thriveLevel');
    const riskLabel = document.getElementById('riskLabel');
    const riskTextarea = document.getElementById('thriveRiskCopy');

    // Remove all previous color classes from both elements
    thriveLevel.classList.remove('thrive-high', 'thrive-medium', 'thrive-low');
    riskLabel.classList.remove('thrive-high', 'thrive-medium', 'thrive-low');

    // Update the Risk label to show the THRIVE level + Risk and apply color coding
    if (thriveLevel.value) {
        riskLabel.textContent = `R: (${thriveLevel.value} Risk)`;

        // Pre-populate the risk textarea with the selected risk level
        if (riskTextarea && !riskTextarea.value.trim()) {
            riskTextarea.value = `${thriveLevel.value} Risk - `;
            riskTextarea.focus(); // Focus on the textarea so user can continue typing
            // Position cursor at the end
            riskTextarea.setSelectionRange(riskTextarea.value.length, riskTextarea.value.length);
        }

        // Apply appropriate color class based on selected value to both elements
        if (thriveLevel.value === 'High') {
            thriveLevel.classList.add('thrive-high');
            riskLabel.classList.add('thrive-high');
        } else if (thriveLevel.value === 'Medium') {
            thriveLevel.classList.add('thrive-medium');
            riskLabel.classList.add('thrive-medium');
        } else if (thriveLevel.value === 'Low') {
            thriveLevel.classList.add('thrive-low');
            riskLabel.classList.add('thrive-low');
        }
    } else {
        riskLabel.textContent = 'R:';
        // Clear the risk textarea if no level is selected
        if (riskTextarea) {
            riskTextarea.value = '';
        }
    }
}

