function removeDuplicateRiskLevel() {
    const thriveLevel = document.getElementById('thriveLevel');
    const riskTextarea = document.getElementById('thriveRiskCopy');

    if (!thriveLevel.value || !riskTextarea.value) {
        return; // No THRIVE level selected or no text in risk field
    }

    const selectedLevel = thriveLevel.value.toLowerCase(); // e.g., "low", "medium", "high"
    let riskText = riskTextarea.value;
    const originalText = riskText;

    // Only process if the text actually contains the risk level pattern
    const hasRiskPattern = new RegExp(`\\b${selectedLevel}\\s+risk\\b`, 'i').test(riskText);
    if (!hasRiskPattern) {
        return; // No duplicate risk level found, don't modify text
    }

    // Create more specific regex patterns to match duplicate risk level phrases
    const patterns = [
        new RegExp(`^\\s*${selectedLevel}\\s+risk\\s*-?\\s*`, 'gi'), // Risk level at start with optional dash
        new RegExp(`\\s+${selectedLevel}\\s+risk\\s*$`, 'gi'), // Risk level at end of text
        new RegExp(`\\b${selectedLevel}\\s+risk\\s*-\\s*(?=\\w)`, 'gi'), // "low risk - " followed by more text
    ];

    // Remove duplicates using each pattern
    patterns.forEach(pattern => {
        riskText = riskText.replace(pattern, '');
    });

    // Clean up any resulting double spaces or leading/trailing whitespace
    riskText = riskText.replace(/\s+/g, ' ').trim();

    // Only update if we actually made changes and the result isn't empty
    if (riskText !== originalText && riskText.length > 0) {
        riskTextarea.value = riskText;
    }
}

